#ifndef EXPRESSION_H
#define EXPRESSION_H

#include "implicant.h"

#include <string>
#include <vector>


class expression
{
private:

    // Number of variables in the Boolean function.
    int variable_count;

    // Selected implicants for the minimized SOP.
    std::vector<implicant> implicants;


public:

    // ========================================================
    // constructors
    // ========================================================

    expression();

    explicit expression(
        int variable_count
    );

    expression(
        int variable_count,
        const std::vector<implicant>& implicants
    );


    // ========================================================
    // implicants
    // ========================================================

    void add_implicant(
        const implicant& value
    );

    void clear();

    const std::vector<implicant>&
    get_implicants() const;


    // ========================================================
    // variable information
    // ========================================================

    int get_variable_count() const;


    // ========================================================
    // SOP
    // ========================================================

    // Convert the selected implicants into
    // Sum of Products.
    //
    // Example:
    //
    // AB' + CD + A'D'

    std::string to_sop() const;


    // ========================================================
    // POS
    // ========================================================

    // Convert the expression into Product of Sums.
    //
    // NOTE:
    // True minimized POS will be generated by the
    // Quine-McCluskey engine using the zero-set of
    // the Boolean function.
    //
    // This class only handles POS representation.

    std::string to_pos(
        const std::vector<implicant>& pos_implicants
    ) const;


    // ========================================================
    // information
    // ========================================================

    // Number of product terms in the SOP.

    int term_count() const;


    // Total number of literals in the SOP.

    int literal_count() const;


    // ========================================================
    // evaluation
    // ========================================================

    // Evaluate the SOP for a binary input.
    //
    // Example:
    //
    // input = {1, 0, 1, 1}
    //
    // means:
    //
    // A = 1
    // B = 0
    // C = 1
    // D = 1

    bool evaluate(
        const std::vector<int>& input
    ) const;


    // ========================================================
    // utility
    // ========================================================

    // True if this expression contains no
    // product terms.

    bool is_zero() const;

    // True if one of the implicants is
    // the universal implicant "----".

    bool is_one() const;
};

#endif


